import sympy as sp

x = sp.Symbol("x", real=True)

def parse_func(code):
    body = code.split("=", 1)[1]
    return sp.sympify(body, locals={"x": x, "Abs": sp.Abs, "exp": sp.exp, "log": sp.log})

def sample_points(domain):
    if domain and ">" in domain:
        lo = 0.05
        return [lo + (10.0 - lo) * i / 199.0 for i in range(200)]
    pts = []
    for i in range(-200, 201):
        v = i * 0.05
        if abs(v) < 1e-6:
            continue
        pts.append(v)
    return pts

def curvature(f, pts):
    d2 = sp.diff(f, x, 2)
    d2 = d2.replace(lambda e: isinstance(e, sp.DiracDelta), lambda e: sp.Integer(0))
    f2 = sp.lambdify(x, d2, "math")
    vals = []
    for p in pts:
        try:
            v = f2(p)
            v = float(v)
        except Exception:
            continue
        if v == v and v not in (float("inf"), float("-inf")):
            vals.append(v)
    return vals

def jensen(f, pts):
    fn = sp.lambdify(x, f, "math")
    ok = []
    for p in pts:
        try:
            v = float(fn(p))
        except Exception:
            continue
        if v == v and abs(v) < 1e12:
            ok.append((p, v))
    ok.sort()
    if len(ok) < 10:
        return None
    conv_viol = conc_viol = 0
    random.seed(0)
    for _ in range(4000):
        a, b = random.sample(ok, 2)
        mid = (a[0] + b[0]) / 2
        try:
            fm = float(fn(mid))
        except Exception:
            continue
        lin = (a[1] + b[1]) / 2
        diff = fm - lin
        tol = 1e-9 + 1e-6 * (abs(fm) + abs(lin))
        if diff > tol:
            conv_viol += 1
        elif diff < -tol:
            conc_viol += 1
    return conv_viol, conc_viol

def classify(code, domain):
    try:
        f = parse_func(code)
    except Exception as e:
        return None, f"parse-fail:{e}"
    pts = sample_points(domain)
    vals = curvature(f, pts)
    tol = 1e-6
    pos = sum(1 for v in vals if v > tol)
    neg = sum(1 for v in vals if v < -tol)
    if pos and neg:
        return "neither", f"f2 pos={pos} neg={neg}"
    if pos:
        return "convex", f"f2 pos={pos} neg={neg}"
    if neg:
        return "concave", f"f2 pos={pos} neg={neg}"
    j = jensen(f, pts)
    if j is None:
        return "convex", "no-info"
    cv, cc = j
    if cv == 0 and cc > 0:
        return "convex", f"jensen cv={cv} cc={cc}"
    if cc == 0 and cv > 0:
        return "concave", f"jensen cv={cv} cc={cc}"
    if cv and cc:
        return "neither", f"jensen cv={cv} cc={cc}"
    return None, f"jensen both-zero cv={cv} cc={cc}"

