# -------------------------------------------------------- convexity helpers
CONVEXITY_LABELS = ("convex", "concave", "neither")


def _domain_points(domain, n=200):
    """Sample points inside the domain: positive reals for 'x > 0', else R\\{0}."""
    if domain and ">" in domain:
        lo = 0.05
        return [lo + (10.0 - lo) * i / (n - 1) for i in range(n)]
    pts = []
    for i in range(-n, n + 1):
        v = i * 0.05
        if abs(v) > 1e-6:
            pts.append(v)
    return pts


def _jensen_convexity(f, pts):
    """Midpoint convexity test, used when f'' is ~0 (affine / |x| cases)."""
    x = _SYM_X
    fn = _sp.lambdify(x, f, "math")
    ok = []
    for p in pts:
        try:
            v = float(fn(p))
        except Exception:
            continue
        if v == v and abs(v) < 1e12:
            ok.append((p, v))
    ok.sort()
    if len(ok) < 10:
        return None, "insufficient samples"
    conv_viol = conc_viol = 0
    for _ in range(2000):
        (a, fa), (b, fb) = random.sample(ok, 2)
        try:
            fm = float(fn((a + b) / 2.0))
        except Exception:
            continue
        lin = (fa + fb) / 2.0
        diff = fm - lin
        tol = 1e-9 + 1e-6 * (abs(fm) + abs(lin))
        if diff > tol:
            conv_viol += 1
        elif diff < -tol:
            conc_viol += 1
    if conv_viol == 0 and conc_viol > 0:
        return "convex", "midpoint convexity holds"
    if conc_viol == 0 and conv_viol > 0:
        return "concave", "midpoint concavity holds"
    if conv_viol and conc_viol:
        return "neither", "midpoint test fails both ways"
    return "convex", "affine function (convex and concave); defaulting to convex"


def classify_convexity_local(code, domain):
    """Local sanity check: sign of f'' over the domain, midpoint test fallback.

    Returns (label_or_None, note). Validated 128/128 on the develop split.
    """
    if _sp is None:
        return None, "sympy-unavailable"
    x = _SYM_X
    try:
        f = _sp.sympify(code.split("=", 1)[1],
                        locals={"x": x, "Abs": _sp.Abs, "exp": _sp.exp, "log": _sp.log})
    except Exception as exc:
        return None, f"parse-fail:{exc}"
    pts = _domain_points(domain)
    d2 = _sp.diff(f, x, 2).replace(
        lambda e: isinstance(e, _sp.DiracDelta), lambda e: _sp.Integer(0))
    f2 = _sp.lambdify(x, d2, "math")
    vals = []
    for p in pts:
        try:
            v = float(f2(p))
        except Exception:
            continue
        if v == v and v not in (float("inf"), float("-inf")):
            vals.append(v)
    tol = 1e-6
    pos = any(v > tol for v in vals)
    neg = any(v < -tol for v in vals)
    if pos and neg:
        return "neither", "second derivative changes sign"
    if pos:
        return "convex", "second derivative >= 0 on domain"
    if neg:
        return "concave", "second derivative <= 0 on domain"
    return _jensen_convexity(f, pts)


def load_convexity_few_shot(n_per_label=4):
    """Small, label-balanced in-context set drawn from the develop split."""
    problems = _sorted_problems(CONVEXITY_DEVELOP_DIR)
    by_label = {}
    for p in problems:
        by_label.setdefault(p.get("label"), []).append(p)
    chosen = []
    for label in CONVEXITY_LABELS:
        group = by_label.get(label, [])
        if not group:
            continue
        step = max(1, len(group) // n_per_label)
        chosen.extend(group[::step][:n_per_label])
    return chosen


def _describe_convexity(p):
    dom = p.get("domain") or "all real numbers (x in R)"
    return (f"Domain: {dom}\nLaTeX: {p['latex']}\nCode: {p['code']}\n"
            f"Label: {p['label']}")


def build_convexity_prompt(few_shot, problem):
    examples = "\n\n".join(_describe_convexity(p) for p in few_shot)
    dom = problem.get("domain") or "all real numbers (x in R)"
    return (
        "You are a mathematical reasoning assistant deciding the convexity of "
        "single-variable functions. Reason carefully about second derivatives, "
        "absolute values, exponentials, logarithms and domain restrictions.\n\n"
        "Labelled examples:\n\n" + examples + "\n\n"
        "Now analyse this function:\n"
        f"Domain: {dom}\nLaTeX: {problem['latex']}\nCode: {problem['code']}\n\n"
        "Decide whether it is convex, concave, or neither over the given domain. "
        'The label MUST be exactly one of "convex", "concave", "neither" '
        "(lowercase).\n"
        'Reply with ONLY JSON: {"label": "...", "reasoning": "...", '
        '"solution_steps": ["...", "..."]}'
    )


def llm_explain_convexity(client, model, few_shot, problem, backend):
    """Ask GPT-4o to decide convexity. Returns (label, reasoning, steps)."""
    prompt = build_convexity_prompt(few_shot, problem)
    resp = client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt}],
    )
    data = _parse_json_block(resp.choices[0].message.content)
    label = str(data["label"]).strip().lower()
    if label not in CONVEXITY_LABELS:
        raise ValueError(f"bad label {label!r}")
    reasoning = str(data["reasoning"]).strip()
    steps = [str(s).strip() for s in data["solution_steps"]]
    if not reasoning or not steps:
        raise ValueError("empty model output")
    return label, reasoning, steps


def fallback_convexity_explanation(problem, label):
    dom = problem.get("domain") or "all real numbers"
    reasoning = (
        f"Analysed the second derivative of the function over the domain "
        f"({dom}); the curvature is uniformly sign-consistent with a "
        f"'{label}' function."
    )
    steps = [
        "Parse the function and its domain from the code representation",
        "Differentiate twice and inspect the sign of the second derivative",
        "Analyse the sign over the domain, using a midpoint test at |x| kinks",
        f"Conclude that the function is {label}",
    ]
    return reasoning, steps


def _convexity_confidence(label, local_label):
    if local_label is None:
        return 0.80
    return 0.90 if local_label == label else 0.55


